// ── Helpers ────────────────────────────────────────────────────────────────────

export function getStateBySlug(slug: string): AuState | undefined {
  return AU_STATES.find(s => s.slug === slug);
}

export function getSuburbBySlug(state: AuState, suburbSlug: string): AuSuburb | undefined {
  return state.suburbs.find(s => s.slug === suburbSlug);
}

export function toSuburbSlug(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
}

/**
 * Parse suburb/state/postcode from a free-text Australian address.
 * Uses POSTCODE_LOOKUP for instant geocoding — no external API needed.
 * Falls back to regex parsing if no postcode found.
 */
export function parseAuAddress(address: string | null | undefined): {
  suburb:   string | null;
  state:    string | null;
  postcode: string | null;
  lat:      number | null;
  lng:      number | null;
} {
  if (!address) return { suburb: null, state: null, postcode: null, lat: null, lng: null };

  // Try to extract postcode from the address string
  const postcodeMatch = address.match(/\b(\d{4})\b/);
  if (postcodeMatch) {
    const info = POSTCODE_LOOKUP[postcodeMatch[1]];
    if (info) {
      return { suburb: info.suburb, state: info.state, postcode: postcodeMatch[1], lat: info.lat, lng: info.lng };
    }
  }

  // Fallback: regex parse "... Suburb STATE POSTCODE" pattern
  const m = address.match(/,?\s+([A-Za-z][A-Za-z\s'-]+?)\s+(ACT|NSW|NT|QLD|SA|TAS|VIC|WA)\s+(\d{4})\s*$/i);
  if (m) return { suburb: m[1].trim(), state: m[2].toUpperCase(), postcode: m[3], lat: null, lng: null };

  // Fallback: just state code
  const stateM = address.match(/\b(ACT|NSW|NT|QLD|SA|TAS|VIC|WA)\b/i);
  if (stateM) return { suburb: null, state: stateM[1].toUpperCase(), postcode: null, lat: null, lng: null };

  return { suburb: null, state: null, postcode: null, lat: null, lng: null };
}
